def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_d = 0
    my_d = 0
    for i in range(n):
        if op[i] == 'D':
            opp_d += 1
        if my[i] == 'D':
            my_d += 1

    opp_rate = opp_d / float(n)

    start5 = n - 5
    if start5 < 0:
        start5 = 0
    d5 = 0
    for i in range(start5, n):
        if op[i] == 'D':
            d5 += 1

    start10 = n - 10
    if start10 < 0:
        start10 = 0
    d10 = 0
    for i in range(start10, n):
        if op[i] == 'D':
            d10 += 1

    run_o = 0
    i = n - 1
    while i >= 0:
        if op[i] == 'D':
            run_o += 1
            i -= 1
        else:
            break

    run_m = 0
    i = n - 1
    while i >= 0:
        if my[i] == 'D':
            run_m += 1
            i -= 1
        else:
            break

    last_m, last_o = history[-1]

    exploitable = False
    if n >= 3 and opp_rate <= 0.25 and d10 <= 2 and d5 <= 1:
        lo = max(1, n - 15)
        for i in range(lo, n):
            if my[i - 1] == 'D' and op[i - 1] == 'C' and my[i] == 'C' and op[i] == 'C':
                exploitable = True
                break

    if exploitable and last_o == 'C' and n < 95:
        return 'D'

    if opp_rate >= 0.55 or d5 >= 5 or (d10 >= 7 and opp_rate >= 0.35):
        if last_o == 'C' and d5 == 0 and opp_rate < 0.7 and rng.random() < 0.08:
            return 'C'
        return 'D'

    if last_o == 'D':
        if n >= 2 and my[-2] == 'D':
            if run_o == 1 and opp_rate <= 0.35:
                return 'C'
            if run_o >= 4 and opp_rate <= 0.45 and rng.random() < 0.3:
                return 'C'
            return 'D'

        if run_o >= 5 and run_m >= 5 and opp_rate <= 0.5:
            return 'C'

        return 'D'

    if last_m == 'D':
        return 'C'

    if n == 98:
        return 'C'

    if opp_rate < 0.08:
        p = 0.02
    elif opp_rate < 0.18:
        p = 0.06
    elif opp_rate < 0.30:
        p = 0.20
    elif opp_rate < 0.45:
        p = 0.50
    elif opp_rate < 0.60:
        p = 0.80
    else:
        p = 0.95

    if rng.random() < p:
        return 'D'

    return 'C'
